"use client";
import { useState } from "react";
import Breadcrumb from "@/components/header/breadcrumb";
import { apiClient, ApiError } from "@/lib/apiClient";

interface UnsubscribePageProps {
  email?: string;
  contactType?: string;
  token?: string;
}

export default function UnsubscribePage({
  email,
  contactType,
  token,
}: UnsubscribePageProps) {
  const [reason, setReason] = useState("");
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState<"idle" | "success" | "error">("idle");
  const [errorMessage, setErrorMessage] = useState("");

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setStatus("idle");
    setErrorMessage("");

    try {
      // apiv3 B2C: POST /newsletter/unsubscribe (tarayıcı → /api/apiv3 proxy).
      const data = await apiClient<{ success: boolean; message?: string }>(
        "/newsletter/unsubscribe",
        {
          method: "POST",
          body: {
            email,
            contact_type: contactType,
            token,
            reason: reason || undefined,
          },
        }
      );

      if (data.success) {
        setStatus("success");
      } else {
        setStatus("error");
        setErrorMessage(data.message || "An error occurred. Please try again.");
      }
    } catch (error) {
      setStatus("error");
      setErrorMessage(
        error instanceof ApiError
          ? error.body?.message || "An error occurred. Please try again."
          : "An error occurred. Please try again."
      );
    } finally {
      setLoading(false);
    }
  };

  const breadcrumb = (
    <Breadcrumb
      items={[
        {
          pageTitle: "Newsletter Unsubscribe",
          pageUrl: "",
        },
      ]}
    />
  );

  const heading = (
    <h1 className="tw-font-display tw-text-[24px] md:tw-text-[28px] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
      Newsletter Unsubscribe
    </h1>
  );

  const cardClass =
    "tw-max-w-[640px] tw-mx-auto tw-mt-6 tw-rounded-2xl tw-border tw-border-solid tw-border-[#eceaf1] tw-bg-white tw-p-6 md:tw-p-8";

  if (!email || !contactType || !token) {
    return (
      <main>
        <div className="tw-max-w-[1320px] tw-mx-auto tw-px-4 tw-py-8 tw-font-display">
          {breadcrumb}
          {heading}
          <div className={cardClass}>
            <div className="tw-text-center tw-py-6">
              <h2 className="tw-text-[20px] tw-font-bold tw-text-[#dc2626] tw-mb-3">
                Invalid Request
              </h2>
              <p className="tw-text-[15px] tw-text-[#5d556c] tw-m-0">
                The unsubscribe link is invalid or expired. Please check your
                email or contact support.
              </p>
            </div>
          </div>
        </div>
      </main>
    );
  }

  if (status === "success") {
    return (
      <main>
        <div className="tw-max-w-[1320px] tw-mx-auto tw-px-4 tw-py-8 tw-font-display">
          {breadcrumb}
          {heading}
          <div className={cardClass}>
            <div className="tw-text-center tw-py-6">
              <svg
                xmlns="http://www.w3.org/2000/svg"
                width="64"
                height="64"
                fill="currentColor"
                className="tw-text-[#16a34a] tw-mb-3 tw-inline-block"
                viewBox="0 0 16 16"
              >
                <path d="M16 8A8 8 0 1 1 0 8a8 8 0 0 1 16 0m-3.97-3.03a.75.75 0 0 0-1.08.022L7.477 9.417 5.384 7.323a.75.75 0 0 0-1.06 1.06L6.97 11.03a.75.75 0 0 0 1.079-.02l3.992-4.99a.75.75 0 0 0-.01-1.05z" />
              </svg>
              <h2 className="tw-text-[20px] tw-font-bold tw-text-[#16a34a] tw-mb-3">
                Successfully Unsubscribed
              </h2>
              <p className="tw-text-[15px] tw-text-[#14101c] tw-mb-2 tw-font-semibold">
                {email}
              </p>
              <p className="tw-text-[15px] tw-text-[#5d556c] tw-m-0">
                You have been successfully unsubscribed from our newsletter.
                <br />
                You will no longer receive emails from us.
              </p>
            </div>
          </div>
        </div>
      </main>
    );
  }

  return (
    <main>
      <div className="tw-max-w-[1320px] tw-mx-auto tw-px-4 tw-py-8 tw-font-display">
        {breadcrumb}
        {heading}
        <div className={cardClass}>
          <div className="tw-text-center tw-mb-6">
            <p className="tw-text-[15px] tw-text-[#5d556c] tw-mb-2">
              You are about to unsubscribe the following email address:
            </p>
            <p className="tw-text-[17px] tw-font-semibold tw-text-[#854ec9] tw-m-0">
              {email}
            </p>
          </div>

          <form onSubmit={handleSubmit}>
            <div className="tw-mb-5">
              <label
                htmlFor="reason"
                className="tw-block tw-text-sm tw-font-medium tw-text-[#14101c] tw-mb-1.5"
              >
                Please tell us why you are unsubscribing (optional)
              </label>
              <textarea
                id="reason"
                className="tw-w-full tw-rounded-xl tw-border tw-border-solid tw-border-[#d6d2de] tw-px-3.5 tw-py-2.5 tw-text-[15px] tw-text-[#14101c] tw-outline-none focus:tw-border-[#854ec9] tw-transition-colors disabled:tw-opacity-60"
                rows={4}
                value={reason}
                onChange={(e) => setReason(e.target.value)}
                placeholder="Your feedback helps us improve..."
                disabled={loading}
              />
            </div>

            {status === "error" && (
              <div
                role="alert"
                className="tw-mb-5 tw-rounded-xl tw-border tw-border-solid tw-border-red-200 tw-bg-red-50 tw-px-4 tw-py-3 tw-text-[14px] tw-text-red-700"
              >
                {errorMessage}
              </div>
            )}

            <button
              type="submit"
              disabled={loading}
              className="tw-w-full tw-inline-flex tw-items-center tw-justify-center tw-gap-1 tw-rounded-full tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-text-white tw-font-semibold tw-text-[15px] tw-px-5 tw-py-3 tw-border-0 tw-cursor-pointer tw-transition-colors disabled:tw-opacity-60 disabled:tw-cursor-not-allowed"
            >
              {loading ? (
                <>
                  <span
                    className="tw-inline-block tw-w-4 tw-h-4 tw-mr-2 tw-rounded-full tw-border-2 tw-border-solid tw-border-current tw-border-r-transparent tw-animate-spin tw-align-[-0.125em]"
                    role="status"
                    aria-hidden="true"
                  />
                  Processing...
                </>
              ) : (
                "Unsubscribe"
              )}
            </button>
          </form>
        </div>
      </div>
    </main>
  );
}
